INSERT INTO article_texts (id, article_id, language, title, summary, body_md, created_at, updated_at) VALUES
  ('76000000-0000-4000-8000-000000000001', '75000000-0000-4000-8000-000000000001', 'en', 'Verstappen masters Monaco', 'A controlled drive from pole.', '# Verstappen masters Monaco
